package com.hau.exam.infrastructure.persistence.adapter;import com.hau.exam.application.port.out.*;import com.hau.exam.domain.model.*;import com.hau.exam.infrastructure.persistence.entity.*;import com.hau.exam.infrastructure.persistence.mapper.TemplateMapper;import com.hau.exam.infrastructure.persistence.repository.*;import java.util.*;import org.springframework.stereotype.Component;
public final class PersistenceAdapters{private PersistenceAdapters(){}
@Component public static class MatrixAdapter implements ExamMatrixRepository{private final Matrices repo;public MatrixAdapter(Matrices r){repo=r;}public ExamMatrix save(ExamMatrix m){var e=toEntity(m);repo.findById(m.id()).ifPresent(x->e.version=x.version);return toDomain(repo.save(e));}public Optional<ExamMatrix>findById(UUID id){return repo.findById(id).map(this::toDomain);}public List<ExamMatrix>findByFaculty(String f){return repo.findAllByFacultyIdOrderByUpdatedAtDesc(f).stream().map(this::toDomain).toList();}private MatrixEntity toEntity(ExamMatrix m){var e=new MatrixEntity();e.id=m.id();e.name=m.name();e.facultyId=m.facultyId();e.subjectId=m.subjectId();e.totalQuestions=m.totalQuestions();e.createdBy=m.createdBy();e.createdAt=m.createdAt();e.updatedAt=m.updatedAt();e.rules=m.rules().stream().map(r->{var x=new MatrixRuleEntity();x.id=r.id()==null?UUID.randomUUID():r.id();x.matrix=e;x.chapterId=r.chapterId();x.topicId=r.topicId();x.difficulty=r.difficulty();x.questionCount=r.questionCount();return x;}).toList();return e;}private ExamMatrix toDomain(MatrixEntity e){return new ExamMatrix(e.id,e.name,e.facultyId,e.subjectId,e.totalQuestions,e.rules.stream().map(r->new ExamMatrixRule(r.id,r.chapterId,r.topicId,r.difficulty,r.questionCount)).toList(),e.createdBy,e.createdAt,e.updatedAt);}}
@Component public static class TemplateAdapter implements ExamTemplateRepository{private final Templates repo;private final TemplateMapper mapper;public TemplateAdapter(Templates r,TemplateMapper m){repo=r;mapper=m;}public ExamTemplate save(ExamTemplate t){return mapper.toDomain(repo.save(mapper.toEntity(t)));}public Optional<ExamTemplate>findById(UUID id){return repo.findById(id).map(mapper::toDomain);}}
@Component public static class ExamAdapter implements ExamRepository{private final Exams repo;public ExamAdapter(Exams r){repo=r;}public Exam save(Exam exam){var e=toEntity(exam);repo.findById(exam.id()).ifPresent(x->e.version=x.version);return toDomain(repo.save(e));}public Optional<Exam>findById(UUID id){return repo.findById(id).map(this::toDomain);}private ExamEntity toEntity(Exam x){var e=new ExamEntity();e.id=x.id();e.name=x.name();e.facultyId=x.facultyId();e.subjectId=x.subjectId();e.matrixId=x.matrixId();e.templateId=x.templateId();e.createdBy=x.createdBy();e.createdAt=x.createdAt();e.updatedAt=x.updatedAt();e.versions=x.versions().stream().map(v->{var ve=new ExamVersionEntity();ve.id=v.id();ve.exam=e;ve.versionNumber=v.versionNumber();ve.createdAt=v.createdAt();ve.questions=v.questions().stream().map(q->{var qe=new ExamQuestionEntity();qe.id=q.id();qe.version=ve;qe.questionId=q.questionId();qe.position=q.position();qe.matrixRuleId=q.matrixRuleId();return qe;}).toList();return ve;}).toList();return e;}private Exam toDomain(ExamEntity e){return new Exam(e.id,e.name,e.facultyId,e.subjectId,e.matrixId,e.templateId,e.createdBy,e.versions.stream().map(v->new ExamVersion(v.id,v.versionNumber,v.questions.stream().map(q->new ExamQuestionReference(q.id,q.questionId,q.position,q.matrixRuleId)).toList(),v.createdAt)).toList(),e.createdAt,e.updatedAt);}}}
